{
  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted = []
    diagnostics = []
    for c in calls:
        call_id = c['call_id']
        loss_without = c['loss_without_call']
        loss_with = c['loss_with_call']
        pred_tokens = c['prediction_tokens']
        parseable = c['parseable']
        if not isinstance(call_id, str) or not call_id:
            raise ValueError("Invalid call_id")
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError("Loss values must be numeric")
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be bool")
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        accept = parseable and normalized_gain >= threshold
        if accept:
            accepted.append(call_id)
        diagnostics.append({
            "call_id": call_id,
            "gain": round(gain, 6),
            "normalized_gain": round(normalized_gain, 6),
            "accepted": accept
        })
    return {
        "accepted_call_ids": accepted,
        "per_call_diagnostics": diagnostics
    }"
}
